/* eslint-disable react/no-unknown-property */
import { FC, useCallback, useEffect, useRef, useState } from 'react';
import { useLogger } from '@dodopizza/react-logger';
import { Canvas } from '@react-three/fiber';
import { Physics } from '@react-three/rapier';
import { NoToneMapping } from 'three';
import useSound from 'use-sound';

import { InstructionsPage } from 'pages/instructions/instructions';
import { GameResult } from 'pages/result/result';
import { Score } from 'pages/score/score';
import { enrichLoggerWithScope, updateLogger } from 'shared/lib/logger';
import gameEndedAudio from '../../app/assets/audio/gameEnded.mp3';
import tapAudio from '../../app/assets/audio/tap.mp3';
import {
	GameEndedEvent,
	GameEnvironmentSettings,
	GameRules,
	GameSettings,
	LossReason,
	PlatformId,
	PointAddedEvent,
} from './event-api.model';
import { ggFinish, ggNotifyLoaded, ggPlatform, ggStartRun, ggTrack, isGgStandalone, Verdict } from 'shared/gg/gg';
import { eventsPublisher, MessageJSON } from './eventPublisher';
import { Floor } from './floor';
import {
	cameraPosition,
	changeCameraPositionAfter,
	getInitialPosition,
	GgTapSnapshot,
	sendEndGameTimeout,
	Triplet,
} from './game.model';
import { BlurEffectStyled, GameContainerStyled } from './game.styles';
import { Scene, SceneHandle } from './scene';

const getRewardAmount = (rules: GameRules | undefined, score: number): number => {
	if (!rules || !score) {
		return 0;
	}

	const reward = Math.floor(score / rules.pointsRatio) * rules.coinsRatio;

	return Math.min(reward, rules.maxCoinsReward);
};

// GG standalone: приложение открыло игру из реестра и не пришлёт initGame/startGame —
// стартуем сами; счёт и награду в этом режиме решает game-connector, не эта формула
const ggEnvironment = (): GameEnvironmentSettings => ({
	client: ggPlatform(),
	clientVersion: `gg-standalone`,
	countryId: 643,
	languageCode: `ru`,
	environmentUrl: ``,
});

const ggSettings = (): GameSettings => ({
	isGameAvailable: true,
	isRewardClaimed: false,
	rewardedCoins: 0,
	orderId: ``,
	clientId: new URLSearchParams(window.location.search).get(`UID`) ?? ``,
	rules: {
		maxCoinsReward: 100,
		pointsPerCoin: 1,
		maxRewardedTowerHeight: 100,
		showResultPage: true,
		showInstructionsPage: false,
		showAddedBoxesCounter: true,
		pointsRatio: 1,
		// 1:1 — награду в этом режиме назначает game-connector, а собственный множитель
		// игры рисовал бы на экране результата другое число, чем пришло в вердикте
		coinsRatio: 1,
	},
});

const getGameEndedEventObject = (score: number, lossReason: LossReason, params?: GameSettings): GameEndedEvent => ({
	score,
	lossReason,
	rewardAmount: getRewardAmount(params?.rules, score),
});

const getPointAddedEventObject = (score: number, params?: GameSettings): PointAddedEvent => ({
	score,
	rewardAmount: getRewardAmount(params?.rules, score),
});

export const Game: FC = () => {
	const ref = useRef<SceneHandle>(null);
	const [showResult, setShowResult] = useState(false);
	const [showInstructions, setShowInstructions] = useState(false);
	const [isGameStarted, setIsGameStarted] = useState(false);
	const [pizzaBoxCount, setPizzaBoxCount] = useState(0);
	const [gameEnvironment, setGameEnvironment] = useState<GameEnvironmentSettings | undefined>(undefined);
	const [gameSettings, setGameSettings] = useState<GameSettings | undefined>();
	const [playGameEndedAudio] = useSound(gameEndedAudio);
	const [playAccurateTap] = useSound(tapAudio);
	const { logInfo, logDebug } = useLogger(`pizza-tower-game`);
	const [isTexturesLoaded, setIsTexturesLoaded] = useState(false);
	const [initialBoxPosition] = useState<Triplet>(getInitialPosition(window.innerHeight));
	const [showBlurEffect, setShowBlurEffect] = useState(false);
	const [gameEndedTimeout, setGameEndedTimeout] = useState<NodeJS.Timeout | undefined>();
	const [ggVerdict, setGgVerdict] = useState<Verdict | null>(null);
	const ggBooted = useRef(false);
	const { gameMode } = window;

	const gameEnded = useCallback(
		(score: number, lossReason: LossReason): void => {
			const gameEndedEvent = getGameEndedEventObject(score, lossReason, gameSettings);
			if (gameSettings?.rules?.showResultPage) {
				setShowResult(true);
			}
			setPizzaBoxCount(score);
			setIsGameStarted(false);
			playGameEndedAudio();
			logInfo(`Game ended. Score: ${score}, lossReason: ${lossReason}`, {
				gameEndedEvent,
				gameEnvironment,
				gameSettings,
			});

			if (isGgStandalone()) {
				ggTrack(`run_ended`, { reason: lossReason, score });
				void ggFinish().then(setGgVerdict);
			}

			const sendEvent = (): void => {
				eventsPublisher.gameEnded(gameEndedEvent, gameEnvironment?.client);
				logDebug(`Game ended event sent`, gameEndedEvent);
			};

			// экспериментально для мобилок сделали задержку.
			if (gameEnvironment?.client === PlatformId.IOS || gameEnvironment?.client === PlatformId.Android) {
				const timeout = setTimeout(() => {
					sendEvent();
				}, sendEndGameTimeout);
				clearTimeout(gameEndedTimeout);
				setGameEndedTimeout(timeout);
			} else {
				sendEvent();
			}
		},
		[gameEndedTimeout, gameEnvironment, gameSettings, logDebug, logInfo, playGameEndedAudio],
	);

	const boxAdded = useCallback(
		(boxCount: number, isAccurateTap: boolean): void => {
			if (isAccurateTap) {
				playAccurateTap();
			}

			if (!showBlurEffect && boxCount === changeCameraPositionAfter) {
				setShowBlurEffect(true);
			}

			setPizzaBoxCount(boxCount);
			const pointAddedEvent = getPointAddedEventObject(boxCount, gameSettings);

			eventsPublisher.pointAdded(pointAddedEvent, gameEnvironment?.client);
		},
		[showBlurEffect, gameSettings, gameEnvironment?.client, playAccurateTap],
	);

	const initGame = useCallback(
		(params?: GameEnvironmentSettings): void => {
			setGameEnvironment(params);
			updateLogger({
				environmentUrl: params?.environmentUrl,
				client: params?.client ?? PlatformId.None,
				clientVersion: params?.clientVersion,
				countryId: params?.countryId,
			});

			logInfo(`Game initialized`, params);
		},
		[logInfo],
	);

	const startGame = useCallback(
		(params?: GameSettings): void => {
			// кнопки Play/Play again передают сюда событие клика вместо настроек —
			// в GG-режиме подставляем свои
			if (isGgStandalone() && !params?.rules) {
				params = ggSettings();
			}
			enrichLoggerWithScope({
				clientId: params?.clientId,
				orderId: params?.orderId,
			});
			logInfo(`Game started`, params);
			setGameSettings(params);
			setPizzaBoxCount(0);
			setShowResult(false);
			if (params?.rules?.showInstructionsPage) {
				setShowInstructions(true);

				return;
			}
			setShowInstructions(false);
			setIsGameStarted(true);
			playAccurateTap();
			setShowBlurEffect(false);
			clearTimeout(gameEndedTimeout);
			if (isGgStandalone()) {
				setGgVerdict(null);
				ggStartRun();
			}
			ref.current?.startGame();
		},
		[logInfo, playAccurateTap, gameEndedTimeout],
	);

	const endGame = useCallback((): void => {
		ref.current?.endGame();
	}, []);

	const messageListener = useCallback((e: MessageEvent): void => {
		if (typeof e.data !== `string`) {
			return;
		}

		const { event, data } = JSON.parse(e.data) as MessageJSON;
		switch (event) {
			case `initGame`:
				if (data) {
					window.initGame(data);
				}
				break;
			case `startGame`:
				if (data) {
					window.startGame(data);
				}
				break;
			case `endGame`:
				window.endGame();
				break;
			default:
				break;
		}
	}, []);

	useEffect(() => {
		try {
			// this function initializes two times.
			// First in index.html in case if client initializes the game right away after a page was loaded but this component isn't rendered yet.
			window.initGame = (params: string) => {
				const settings = params ? (JSON.parse(params) as GameEnvironmentSettings) : undefined;
				initGame(settings);
			};
			// in case of if settings was set in index.html
			if (window.gameEnvironmentSettings) {
				initGame(window.gameEnvironmentSettings);
			}

			window.startGame = (params: string) => {
				const settings = params ? (JSON.parse(params) as GameSettings) : undefined;
				startGame(settings);
			};

			window.endGame = () => {
				endGame();
			};

			window.addEventListener(`message`, messageListener);

			return () => {
				window.removeEventListener(`message`, messageListener);
			};
		} catch (error) {
			logInfo(`unknown message`, error);
		}
	}, [initGame, startGame, endGame, logInfo, messageListener]);

	// GG standalone: реестровый вебвью не зовёт initGame/startGame — поднимаемся сами.
	// Ждём текстуры (до них Scene не смонтирована и ref.current пуст) и показываем
	// экран инструкций: партию начинает игрок кнопкой, иначе первая коробка уезжает мимо.
	useEffect(() => {
		if (!isGgStandalone() || ggBooted.current || !isTexturesLoaded) {
			return;
		}
		ggBooted.current = true;
		ggNotifyLoaded();
		initGame(ggEnvironment());
		setGameSettings(ggSettings());
		setShowInstructions(true);
	}, [initGame, isTexturesLoaded]);

	const ggTapped = useCallback((snapshot: GgTapSnapshot): void => {
		if (isGgStandalone()) {
			ggTrack(`tap`, snapshot);
		}
	}, []);

	const texturesLoaded = useCallback(() => setIsTexturesLoaded(true), []);

	useEffect(() => {
		if (isTexturesLoaded && gameEnvironment?.client) {
			logInfo(`Sending gameLoaded event`, { client: gameEnvironment.client });
			eventsPublisher.gameLoaded(gameEnvironment.client);
		}
	}, [gameEnvironment?.client, isTexturesLoaded, logInfo]);

	useEffect(() => {
		const handle = (event: KeyboardEvent): void => {
			if (!isGameStarted && event.code === `Space`) {
				startGame();
			}
		};

		document.addEventListener(`keydown`, handle);

		return () => {
			document.removeEventListener(`keydown`, handle);
		};
	});

	return (
		<GameContainerStyled $gameMode={gameMode}>
			<Canvas
				dpr={[1, 2]}
				gl={{ antialias: true, toneMapping: NoToneMapping }}
				linear
				orthographic
				camera={{
					position: cameraPosition,
					near: 0,
					far: 400,
					zoom: 100,
				}}
			>
				<Physics timeStep={1 / 60}>
					<Scene
						ref={ref}
						gameEnded={gameEnded}
						boxAdded={boxAdded}
						texturesLoaded={texturesLoaded}
						initialBoxPosition={initialBoxPosition}
						tapped={ggTapped}
					/>
					{!isGameStarted && <Floor initialBoxPosition={initialBoxPosition} />}
				</Physics>
			</Canvas>
			{showResult && <GameResult pizzaBoxCount={pizzaBoxCount} startGame={startGame} />}
			{ggVerdict && (
				<div
					style={{
						position: `fixed`,
						// низ, а не верх: сверху баннер попадает в safe area и под кнопку закрытия
						bottom: `calc(16px + env(safe-area-inset-bottom))`,
						left: 12,
						right: 12,
						zIndex: 20,
						padding: `12px 16px`,
						borderRadius: 12,
						textAlign: `center`,
						fontWeight: 700,
						color: `#fff`,
						background: ggVerdict.status === `accepted` ? `#2e7d32` : `#c62828`,
					}}
				>
					{ggVerdict.status === `accepted`
						? `✅ Сервер подтвердил счёт ${ggVerdict.serverScore}: +${ggVerdict.reward.points}`
						: `⛔ Сервер отклонил партию (${ggVerdict.rejectReason ?? ``})`}
				</div>
			)}
			{showInstructions && <InstructionsPage startGame={startGame} />}
			{isGameStarted && (showInstructions || isGgStandalone()) && <Score score={pizzaBoxCount} />}
			{isGameStarted && showBlurEffect && <BlurEffectStyled $gameMode={gameMode} />}
		</GameContainerStyled>
	);
};
