export enum PlatformId {
	None = 0,
	Android = 1,
	IOS = 2,
	Web = 3,
}

export type GameEnvironmentSettings = {
	client: PlatformId; // enum PlatformId 0-none, 1-android, 2-ios
	clientVersion: string;
	countryId: number;
	languageCode: string;
	environmentUrl: string;
};

export type GameRules = {
	maxCoinsReward: number;
	pointsPerCoin: number;
	maxRewardedTowerHeight: number;
	showResultPage: boolean;
	showInstructionsPage: boolean;
	showAddedBoxesCounter: boolean;
	pointsRatio: number;
	coinsRatio: number;
};

export type GameSettings = {
	isGameAvailable: boolean;
	isRewardClaimed: boolean;
	rewardedCoins: number;
	rules?: GameRules;
	settings?: Map<string, string>;
	orderId: string;
	clientId: string;
};

export type GameEndedEvent = {
	score: number;
	lossReason: LossReason;
	rewardAmount?: number;
};

export type PointAddedEvent = {
	score: number;
	rewardAmount?: number;
};

export enum LossReason {
	None = 0,
	BeyoundScreen = 1,
	NoOverlap = 2,
	TowerCollapsed = 3,
}
