import { getTextureBoxes } from 'src/pages/game/textureBoxes';
import { Euler } from 'three';

import { LossReason } from './event-api.model';

export type Triplet = [x: number, y: number, z: number];
export enum Direction {
	X = 0,
	Y = 1,
	Z = 2,
}

export const getDirectionValue = (triplet: Triplet, direction: Direction): number => {
	switch (direction) {
		case Direction.X:
			return triplet[0];
		case Direction.Y:
			return triplet[1];
		case Direction.Z:
			return triplet[2];
		default:
			return 0;
	}
};

export const addTriplet = (triplet1: Triplet, triplet2: Triplet): Triplet => [
	triplet1[0] + triplet2[0],
	triplet1[1] + triplet2[1],
	triplet1[2] + triplet2[2],
];
export const addToDirection = (triplet: Triplet, amount: number, direction: Direction): Triplet => {
	const delta: Triplet = [
		direction === Direction.X ? amount : 0,
		direction === Direction.Y ? amount : 0,
		direction === Direction.Z ? amount : 0,
	];

	return addTriplet(triplet, delta);
};
export const replaceAtDirection = (triplet: Triplet, newValue: number, direction: Direction): Triplet => [
	direction === Direction.X ? newValue : triplet[0],
	direction === Direction.Y ? newValue : triplet[1],
	direction === Direction.Z ? newValue : triplet[2],
];

export const getDifference = (position: Triplet, previousPosition: Triplet, direction: Direction): number => {
	switch (direction) {
		case Direction.X:
			return position[0] - previousPosition[0];
		case Direction.Y:
			return position[1] - previousPosition[1];
		case Direction.Z:
			return position[2] - previousPosition[2];
		default:
			return 0;
	}
};

export const getRandomInt = (start: number, end: number): number => {
	const min = Math.ceil(start);
	const max = Math.floor(end);

	return Math.floor(Math.random() * (max - min + 1) + min);
};

