export const cameraPosition: Triplet = [2, 2, 2];
export const originalBoxSize: Triplet = [1.5, 0.25, 1.5];
export const newBoxPosition = -5;
export const mass = 5;
export const boxDurationSeconds = 2; // duration for a box to move
export const speed = (Math.abs(newBoxPosition) * 2) / boxDurationSeconds; // units per second
export const fallingBoxGravityScale = 1;
export const boxGravityScale = 0.3;
const overlapInPercentThatNotCutBox = 0.05;
const initialPosition: Triplet = [0, -3, 0];
const initialPositionForSmallDevices: Triplet = [0, -2, 0];
export const changeCameraPositionAfter = 10;
export type BoxTexture = {
	leftSide: string;
	rightSide: string;
	upperSide: string;
};
export const sendEndGameTimeout = 2000;

export const getRandomPicture = (currentBoxTexture: BoxTexture | null = null): BoxTexture => {
	const textureBoxes = getTextureBoxes();

	const randomnumber = getRandomInt(0, textureBoxes.length - 1);
	const box = textureBoxes[randomnumber];

	return box.upperSide === currentBoxTexture?.upperSide ? getRandomPicture(currentBoxTexture) : box;
};

let changeBoxAfterBoxNumber = getRandomInt(1, 2);

export const getPicture = (boxNumber: number, currentBoxTexture: BoxTexture | null = null): BoxTexture => {
	if (!currentBoxTexture) {
		return getRandomPicture();
	}

	if (boxNumber % changeBoxAfterBoxNumber === 0) {
		changeBoxAfterBoxNumber = getRandomInt(1, 2);

		return getRandomPicture(currentBoxTexture);
	}

	return currentBoxTexture;
};

export const getBoxesUrls = (): string[] => {
	const allUsedBoxes = getTextureBoxes();

	return [
		...allUsedBoxes.map(m => m.leftSide),

		...allUsedBoxes.map(m => m.rightSide),

		...allUsedBoxes.map(m => m.upperSide),
	];
};

export const shouldCutBox = (size: number, difference: number): boolean => {
	const differenceInPercent = Math.abs(difference) / size;

	return differenceInPercent > overlapInPercentThatNotCutBox;
};

export const getInitialPosition = (height: number): Triplet => {
	if (height > 667) {
		return initialPosition;
	}

	return initialPositionForSmallDevices;
};
