/* eslint-disable @typescript-eslint/no-unsafe-assignment */
/* eslint-disable react/no-unknown-property */
import { memo, useMemo } from 'react';
import { Box, ShapeProps, useTexture } from '@react-three/drei';
import { BoxGeometryProps } from '@react-three/fiber';
import { RigidBody, RigidBodyOptions } from '@react-three/rapier';
import { BoxGeometry } from 'three';

import { BoxTexture, originalBoxSize, TextureOffset } from './game.model';

export const PizzaBoxMaterial = memo(
	(
		props: ShapeProps<typeof BoxGeometry> & {
			boxTexture: BoxTexture;
			textureOffset: TextureOffset;
		},
	): JSX.Element => {
		const { args, boxTexture, textureOffset } = props;

		const [leftpizza, rightpizza, upperpizza] = useTexture([
			boxTexture.leftSide,

			boxTexture.rightSide,

			boxTexture.upperSide,
		]);

		const [material0, material2, material4] = useMemo(() => {
			const leftpizzaClone = leftpizza.clone();

			const upperpizzaClone = upperpizza.clone();

			const rightpizzaClone = rightpizza.clone();

			if (args && args[0] && args[2]) {
				const textureOffsetX = textureOffset.x / originalBoxSize[0];
				const textureOffsetY = textureOffset.y / originalBoxSize[2];
				const x = args[0] / originalBoxSize[0];
				const y = args[2] / originalBoxSize[2];

				leftpizzaClone.repeat.setX(x);
				leftpizzaClone.offset.setX(textureOffsetX);

				rightpizzaClone.repeat.setX(y);
				rightpizzaClone.offset.setX(textureOffsetY);

				upperpizzaClone.repeat.set(x, y);
				upperpizzaClone.offset.set(textureOffsetX, textureOffsetY);
			}

			return [leftpizzaClone, upperpizzaClone, rightpizzaClone];
		}, [leftpizza, rightpizza, upperpizza, args, textureOffset]);

		return (
			<>
				<meshBasicMaterial map={material4} attach='material-0' />

				<meshBasicMaterial map={material4} attach='material-1' />

				<meshBasicMaterial map={material2} attach='material-2' />

				<meshBasicMaterial map={material2} attach='material-3' />

				<meshBasicMaterial map={material0} attach='material-4' />

				<meshBasicMaterial map={material0} attach='material-5' />
			</>
		);
	},
);

export const PizzaBox = memo(
	(
		props: ShapeProps<typeof BoxGeometry> &
			RigidBodyOptions &
			BoxGeometryProps & {
				boxTexture: BoxTexture;
				pizzaBoxId: string;
				textureOffset: TextureOffset;
			},
	): JSX.Element => {
		const { position, type, args, boxTexture, mass, pizzaBoxId, gravityScale, textureOffset } = props;

		return (
			<RigidBody
				userData={{ id: pizzaBoxId }}
				mass={mass}
				type={type}
				position={position}
				args={args}
				gravityScale={gravityScale}
			>
				<Box args={args}>
					<boxGeometry args={args} />

					<PizzaBoxMaterial args={args} boxTexture={boxTexture} textureOffset={textureOffset} />
				</Box>
			</RigidBody>
		);
	},
);
