/**
 * GG standalone mode: игра открыта из реестра игр (generic-вебвью),
 * identity — подписанные query-параметры приложения, счёт валидирует game-connector.
 */
import { PlatformId } from 'pages/game/event-api.model';

import { GgSession, sendGameLoaded, Verdict } from '@dodopizza/game-sdk';

/**
 * Сообщить хосту, что игра готова. Обязательно ДО старта партии:
 * приложение держит нативный лоадер до этого сигнала, а игрок не нажмёт Play
 * из-под лоадера — получился бы дедлок.
 */
export const ggNotifyLoaded = (): void => sendGameLoaded();

declare global {
	interface Window {
		ggConnectorUrl?: string;
	}
}

// ponytail: адрес демо-туннеля по умолчанию; на стенде задаётся window.ggConnectorUrl
const DEFAULT_CONNECTOR = `https://1ac9-5-152-127-109.ngrok-free.app`;

const connectorUrl = (): string => window.ggConnectorUrl ?? DEFAULT_CONNECTOR;

// free-ngrok отдаёт браузерам HTML-заглушку без этого заголовка
const fetchImpl: typeof fetch = (url, init = {}) =>
	fetch(url, { ...init, headers: { ...(init.headers ?? {}), 'ngrok-skip-browser-warning': `1` } });

export const isGgStandalone = (): boolean => new URLSearchParams(window.location.search).has(`UID`);

export const ggPlatform = (): PlatformId => {
	if (/iPhone|iPad|iPod/.test(navigator.userAgent)) {
		return PlatformId.IOS;
	}

	return /Android/.test(navigator.userAgent) ? PlatformId.Android : PlatformId.Web;
};

let current: Promise<GgSession> | null = null;

/** Новая партия = новая сессия коннектора. События буферизуются через promise-цепочку. */
export const ggStartRun = (): void => {
	if (!isGgStandalone()) {
		return;
	}

	current = GgSession.init(`pizza-tower`, { connectorUrl: connectorUrl(), fetchImpl });
	void current
		.then(s => s.track(`run_started`))
		// eslint-disable-next-line no-console
		.catch(e => console.warn(`gg: session init failed`, e));
};

export const ggTrack = (type: string, payload: unknown): void => {
	void current?.then(s => s.track(type, payload)).catch(() => undefined);
};

export const ggFinish = async (): Promise<Verdict | null> => {
	if (!current) {
		return null;
	}

	try {
		const session = await current;

		return await session.finish();
	} catch {
		return null;
	}
};

export type { Verdict };
