import { Box } from '@react-three/drei';
import { RigidBody } from '@react-three/rapier';

import { Triplet } from './game.model';

export type FloorProp = {
	initialBoxPosition: Triplet;
};

export const Floor = (prop: FloorProp): JSX.Element => {
	const { initialBoxPosition } = prop;

	return (
		<RigidBody type='fixed' name='floor'>
			<Box position={initialBoxPosition} rotation={[0, 0, 0]} args={[20, 0, 20]}>
				<shadowMaterial opacity={0.2} />
			</Box>
		</RigidBody>
	);
};
