/* eslint-disable react/no-unknown-property */
import { forwardRef, useEffect, useImperativeHandle, useRef, useState } from 'react';
import { Box, GradientTexture, useTexture } from '@react-three/drei';
import { useFrame, useThree } from '@react-three/fiber';
import { useRapier } from '@react-three/rapier';
import { damp3 } from 'maath/easing';
import { Euler, Mesh, Vector3 } from 'three';
import { useImmer } from 'use-immer';

import { LossReason } from './event-api.model';
import {
	AccurateBoxHitEffect,
	addToDirection,
	boxGravityScale,
	BoxTexture,
	cameraPosition,
	changeCameraPositionAfter,
	Direction,
	fallingBoxGravityScale,
	getBoxesUrls,
	getDifference,
	getDirectionValue,
	getPicture,
	mass,
	newBoxPosition,
	NoTextureOffset,
	originalBoxSize,
	PizzaBoxProps,
	replaceAtDirection,
	SceneProp,
	shouldCutBox,
	speed,
	TextureOffset,
	Triplet,
} from './game.model';
import { PizzaBox, PizzaBoxMaterial } from './pizza-box';

const getMass = (currentBoxSize: Triplet): number => {
	let result = mass;
	result *= currentBoxSize[0] / originalBoxSize[0]; // Reduce mass proportionately by size
	result *= currentBoxSize[2] / originalBoxSize[2]; // Reduce mass proportionately by size

	return result;
};

const getDynamicBoxTargetPosition = (position: Triplet, direction: Direction, topLayerPosition: Triplet): Triplet => {
	const targetPosition = Math.abs(newBoxPosition);
	switch (direction) {
		case Direction.X:
			return [targetPosition, position[1], topLayerPosition[2]];
		case Direction.Z:
			return [topLayerPosition[0], position[1], targetPosition];
		default:
			return position;
	}
};

const isBeyoundScreen = (position: Triplet, direction: Direction): boolean =>
	getDirectionValue(position, direction) >= Math.abs(newBoxPosition);

const getPizzaBox = (props: PizzaBoxProps): JSX.Element => (
	<PizzaBox
		pizzaBoxId={props.id}
		key={props.id}
		position={props.position}
		args={props.args}
		mass={props.mass}
		type={props.type}
		boxTexture={props.boxTexture}
		gravityScale={props.gravityScale}
		textureOffset={props.textureOffset}
	/>
);

const getBottomBoxProps = (initialBoxPosition: Triplet): PizzaBoxProps => ({
	position: initialBoxPosition,
	args: originalBoxSize,
	id: `BottomBox`,
	type: `fixed`,
	direction: Direction.X,
	mass: 5,
	boxTexture: getPicture(0),
	gravityScale: boxGravityScale,
	textureOffset: NoTextureOffset,
});

const getNewPizzaBoxProps = (
	previousBoxArgs: Triplet,
	previousBoxPosition: Triplet,
	direction: Direction,
	boxNumber: number,
	previousBoxTexture: BoxTexture,
	textureOffset?: TextureOffset,
): PizzaBoxProps => {
	const newX = direction === Direction.X ? newBoxPosition : previousBoxPosition[0];
	const newZ = direction === Direction.Z ? newBoxPosition : previousBoxPosition[2];
	const newPosition: Triplet = [newX, previousBoxPosition[1] + originalBoxSize[1], newZ];
	const pizzaBoxProps: PizzaBoxProps = {
		position: newPosition,
		args: previousBoxArgs, // New layer has the same size as the cut top layer
		id: new Date().getTime().toString(),
		type: `dynamic`,
		direction,
		mass: 0,
		boxTexture: getPicture(boxNumber + 1, previousBoxTexture),
		gravityScale: boxGravityScale,
		textureOffset: textureOffset ?? NoTextureOffset,
	};

	return pizzaBoxProps;
};

const getCutPizzaBoxProps = (
	args: Triplet,
	position: Triplet,
	boxTexture: BoxTexture,
	textureOffset?: TextureOffset,
): PizzaBoxProps => ({
	args,
	position,
	id: `cut${new Date().getTime().toString()}`,
	type: `dynamic`,
	direction: Direction.Y,
	mass: getMass(args),
	boxTexture,
	gravityScale: boxGravityScale,
	textureOffset: textureOffset ?? NoTextureOffset,
});

const getFallingPizzaBoxProps = (
	args: Triplet,
	position: Triplet,
	boxTexture: BoxTexture,
	textureOffset?: TextureOffset,
): PizzaBoxProps => ({
	direction: Direction.Y,
	position,
	args,
	type: `dynamic`,
	mass: getMass(args),
	id: `FallingPizzaBox${new Date().getTime().toString()}`,
	boxTexture,
	gravityScale: fallingBoxGravityScale,
	textureOffset: textureOffset ?? NoTextureOffset,
});

const getInitialPizzaBox = (previousBoxTexture: BoxTexture, initialBoxPosition: Triplet): PizzaBoxProps =>
	getNewPizzaBoxProps(originalBoxSize, initialBoxPosition, Direction.X, 1, previousBoxTexture);

export type SceneHandle = {
	startGame: () => void;
	endGame: () => void;
};

export const Scene = forwardRef<SceneHandle, SceneProp>((prop, ref): JSX.Element => {
	const { initialBoxPosition } = prop;
	const [bottomBox] = useState<PizzaBoxProps>(getBottomBoxProps(initialBoxPosition));
	const [pizzaBoxes, setPizzaBoxes] = useImmer<PizzaBoxProps[]>([]);
	const [fallingPizzaBoxes, setFallingPizzaBoxes] = useImmer<PizzaBoxProps[]>([]);
	const camera = useThree(x => x.camera);
	const [isGameStarted, setIsGameStarted] = useState(false);
	const [dynamicPizzaBox, setDynamicPizzaBox] = useState<PizzaBoxProps>(
		getInitialPizzaBox(bottomBox.boxTexture, initialBoxPosition),
	);
	const [currentCameraPosition, setCurrentCameraPosition] = useState<Vector3>(
		new Vector3().fromArray(cameraPosition),
	);
	const [accurateBoxHitEffect, setAccurateBoxHitEffect] = useState<AccurateBoxHitEffect>({
		isVisible: false,
	} as AccurateBoxHitEffect);
	const accurateBoxHitEffectRef = useRef<Mesh>(null!);

	useTexture(getBoxesUrls(), () => {
		prop.texturesLoaded();
	});

	// eslint-disable-next-line @typescript-eslint/no-non-null-assertion
	const dynamicBoxRef = useRef<Mesh>(null!);
	const { rigidBodyStates } = useRapier();

	const getPreviousPizzaBox = (): PizzaBoxProps =>
		pizzaBoxes.length === 0 ? bottomBox : pizzaBoxes[pizzaBoxes.length - 1];
	const getBoxPositionById = (id: string): Vector3 | undefined => {
		const state = [...rigidBodyStates.values()].find(val => (val.rigidBody.userData as { id: string }).id === id);

		return state?.object.position;
	};

	const getTopLayerBoxRotation = (): Euler | undefined => {
		const previousBox = getPreviousPizzaBox();
		const state = [...rigidBodyStates.values()].find(
			val => (val.rigidBody.userData as { id: string }).id === previousBox.id,
		);

		return state?.object.rotation;
	};

	const getTopLayerPosition = (): Triplet => {
		const previousBox = getPreviousPizzaBox();

		const vector = getBoxPositionById(previousBox.id);

		return vector?.toArray() ?? previousBox.position;
	};

	const checkIfTopBoxFalls = (): boolean => {
		const previousBox = getPreviousPizzaBox();

		const previousBoxPosition = getTopLayerPosition();

		return Math.abs(previousBox.position[1] - previousBoxPosition[1]) > 0.75;
	};

	const getPizzaBoxesCount = (): number => pizzaBoxes.length;

	const getDynamicBoxPosition = (): Triplet => dynamicBoxRef.current.position.toArray();

	const setCameraPositionAfterEndGame = (): void => {
		camera.zoom = Math.max(50, 100 - pizzaBoxes.length / 2);
		setCurrentCameraPosition(new Vector3().fromArray(cameraPosition));
	};

	const setNewCameraPosition = (): void => {
		if (pizzaBoxes.length < changeCameraPositionAfter) {
			return;
		}
		if (camera.position.y < originalBoxSize[1] * (pizzaBoxes.length - 1) + cameraPosition[1]) {
			const cameraShift = new Vector3(0, originalBoxSize[1], 0);
			setCurrentCameraPosition(camera.position.clone().add(cameraShift));
		}
	};

	const setInitialCameraPosition = (): void => {
		camera.zoom = 100;
		camera.position.fromArray(cameraPosition);
	};

	const addPizzaBoxToTower = (
		args: Triplet,
		position: Triplet,
		boxTexture: BoxTexture,
		pictureOffset?: TextureOffset,
	): void => {
		const pizzaBox = getCutPizzaBoxProps(args, position, boxTexture, pictureOffset);
		setPizzaBoxes([...pizzaBoxes, pizzaBox]);
	};
	const addFallingPizzaBox = (
		args: Triplet,
		position: Triplet,
		boxTexture: BoxTexture,
		pictureOffset?: TextureOffset,
	): void => {
		const fallingPizzaBox = getFallingPizzaBoxProps(args, position, boxTexture, pictureOffset);
		setFallingPizzaBoxes([...fallingPizzaBoxes, fallingPizzaBox]);
	};
	const addDynamicPizzaBox = (
		args: Triplet,
		position: Triplet,
		direction: Direction,
		previousBoxTexture: BoxTexture,
		pictureOffset?: TextureOffset,
	): void => {
		const newPizzaBoxProps = getNewPizzaBoxProps(
			args,
			position,
			direction,
			pizzaBoxes.length + 1,
			previousBoxTexture,
			pictureOffset,
		);
		setDynamicPizzaBox(newPizzaBoxProps);
	};

	const startGame = (): void => {
		setPizzaBoxes([]);
		setFallingPizzaBoxes([]);
		setDynamicPizzaBox(getInitialPizzaBox(bottomBox.boxTexture, initialBoxPosition));
		setIsGameStarted(true);
		setInitialCameraPosition();
	};
	const endGame = (lossReason: LossReason): void => {
		setIsGameStarted(false);
		setDynamicPizzaBox(getInitialPizzaBox(dynamicPizzaBox.boxTexture, initialBoxPosition));
		addFallingPizzaBox(
			dynamicPizzaBox.args,
			getDynamicBoxPosition(),
			dynamicPizzaBox.boxTexture,
			dynamicPizzaBox.textureOffset,
		);
		prop.gameEnded(getPizzaBoxesCount(), lossReason);
		setCameraPositionAfterEndGame();
	};

	const getTextureOffset = (
		pictureOffset: TextureOffset,
		direction: Direction,
		difference: number,
	): TextureOffset => {
		if (direction === Direction.X && difference < 0) {
			return { x: pictureOffset.x + Math.abs(difference), y: pictureOffset.y };
		}
		if (direction === Direction.Z && difference > 0) {
			return { x: pictureOffset.x, y: pictureOffset.y + Math.abs(difference) };
		}

		return pictureOffset;
	};

	const getFallingPizzaBoxTextureOffset = (
		pictureOffset: TextureOffset,
		direction: Direction,
		difference: number,
	): TextureOffset => {
		if (direction === Direction.X && difference > 0) {
			return { x: pictureOffset.x + Math.abs(difference), y: pictureOffset.y };
		}
		if (direction === Direction.Z && difference < 0) {
			return { x: pictureOffset.x, y: pictureOffset.y + Math.abs(difference) };
		}

		return pictureOffset;
	};

	const addNextBoxesWithCutAndFallingBoxes = (
		args: Triplet,
		overhangSize: number,
		direction: Direction,
		position: Triplet,
		difference: number,
		textureOffset: TextureOffset,
		size: number,
		previousBoxPosition: Triplet,
	): void => {
		const cutPizzaBoxSize = addToDirection(args, -overhangSize, direction);
		const cutPizzaBoxPosition = addToDirection(position, -difference / 2, direction);
		const cutTextureOffset = getTextureOffset(textureOffset, direction, difference);
		addPizzaBoxToTower(cutPizzaBoxSize, cutPizzaBoxPosition, dynamicPizzaBox.boxTexture, cutTextureOffset);

		// Overhang
		const overhangShift = (size / 2) * Math.sign(difference); // should be `(size / 2 + difference) * Math.sign(difference)`?
		const fallingPizzaBoxSize = replaceAtDirection(args, overhangSize, direction);
		const fallingPizzaBoxPosition = addToDirection(position, overhangShift, direction);
		const fallingTextureOffset = getFallingPizzaBoxTextureOffset(textureOffset, direction, difference);
		addFallingPizzaBox(
			fallingPizzaBoxSize,
			fallingPizzaBoxPosition,
			dynamicPizzaBox.boxTexture,
			fallingTextureOffset,
		);

		const nextDirection = direction === Direction.X ? Direction.Z : Direction.X;
		const newDynamicBoxY = previousBoxPosition[1] + originalBoxSize[1]; // based on actual tower height
		const dynamicBoxPosition = replaceAtDirection(cutPizzaBoxPosition, newDynamicBoxY, Direction.Y);
		addDynamicPizzaBox(
			cutPizzaBoxSize,
			dynamicBoxPosition,
			nextDirection,
			dynamicPizzaBox.boxTexture,
			cutTextureOffset,
		);
	};

	const addNextBoxes = (direction: Direction, previousBoxPosition: Triplet): void => {
		addPizzaBoxToTower(
			dynamicPizzaBox.args,
			[previousBoxPosition[0], previousBoxPosition[1] + originalBoxSize[1], previousBoxPosition[2]],
			dynamicPizzaBox.boxTexture,
			dynamicPizzaBox.textureOffset,
		);

		const nextDirection = direction === Direction.X ? Direction.Z : Direction.X;
		const newDynamicBoxY = previousBoxPosition[1] + originalBoxSize[1]; // based on actual tower height
		const dynamicBoxPosition = replaceAtDirection(previousBoxPosition, newDynamicBoxY, Direction.Y);
		addDynamicPizzaBox(
			dynamicPizzaBox.args,
			dynamicBoxPosition,
			nextDirection,
			dynamicPizzaBox.boxTexture,
			dynamicPizzaBox.textureOffset,
		);

		const accurateBoxHitArgs: Triplet = [dynamicPizzaBox.args[0], 0.01, dynamicPizzaBox.args[2]];
		// add animation
		setAccurateBoxHitEffect({
			isVisible: true,
			position: [
				previousBoxPosition[0],
				previousBoxPosition[1] + dynamicPizzaBox.args[1] / 2,
				previousBoxPosition[2],
			],
			args: accurateBoxHitArgs,
			opacity: 1,
			initialArgs: dynamicPizzaBox.args,
			rotation: getTopLayerBoxRotation(),
		});
	};

	useImperativeHandle(ref, () => ({
		startGame: () => startGame(),
		endGame: () => endGame(LossReason.None),
	}));

	const userTouch = (): void => {
		if (!isGameStarted) {
			return;
		}

		const previousBoxPosition = getTopLayerPosition();
		const { direction, args, textureOffset } = dynamicPizzaBox;
		const position = getDynamicBoxPosition();

		const size = getDirectionValue(args, direction);
		const difference = getDifference(position, previousBoxPosition, direction);
		const overhangSize = Math.abs(difference);
		const overlapSize = size - overhangSize;

		prop.tapped?.({
			boxSize: args,
			overhang: overhangSize,
			cut: shouldCutBox(size, difference),
			n: pizzaBoxes.length + 1,
			boxPos: position,
			topPos: previousBoxPosition,
		});

		if (overlapSize <= 0) {
			endGame(LossReason.NoOverlap);

			return;
		}

		const shouldCutPizzaBox = shouldCutBox(size, difference);
		// cut box
		if (shouldCutPizzaBox) {
			addNextBoxesWithCutAndFallingBoxes(
				args,
				overhangSize,
				direction,
				position,
				difference,
				textureOffset,
				size,
				previousBoxPosition,
			);
		} else {
			addNextBoxes(direction, previousBoxPosition);
		}

		// needed to stop render movement of dynamic box
		// because useFrame() render might happen before the state is updated by react
		// and box will move after the cut position
		dynamicBoxRef.current.userData.isMoving = false;

		prop.boxAdded(pizzaBoxes.length + 1, !shouldCutPizzaBox);
		setNewCameraPosition();
	};

	useEffect(() => {
		const handle = (): void => {
			userTouch();
		};

		document.addEventListener(`pointerdown`, handle);
		document.addEventListener(`keydown`, handle);

		return () => {
			document.removeEventListener(`pointerdown`, handle);
			document.removeEventListener(`keydown`, handle);
		};
	});

	useEffect(() => {
		// eslint-disable-next-line @typescript-eslint/no-unnecessary-condition
		if (dynamicBoxRef.current) {
			dynamicBoxRef.current.userData.isMoving = true;
		}
	}, [dynamicPizzaBox]);

	const frameAccurateBoxHitEffect = (): void => {
		if (accurateBoxHitEffect.isVisible) {
			const newArgs: Triplet = [
				accurateBoxHitEffect.args[0] + 0.005,
				accurateBoxHitEffect.args[1],
				accurateBoxHitEffect.args[2] + 0.005,
			];
			let isVisible = true;

			const animationLimit = accurateBoxHitEffect.initialArgs[0] / 10;

			if (newArgs[0] > accurateBoxHitEffect.initialArgs[0] + animationLimit) {
				isVisible = false;
			}
			setAccurateBoxHitEffect({
				...accurateBoxHitEffect,
				args: newArgs,
				isVisible,
				opacity: accurateBoxHitEffect.opacity - 0.1,
			});
		}
	};

	useFrame((_state, delta) => {
		camera.position.lerp(currentCameraPosition, delta);
		if (!isGameStarted || !dynamicBoxRef.current.userData.isMoving) {
			return;
		}

		const { direction } = dynamicPizzaBox;
		const position = getDynamicBoxPosition();
		const targetPosition = getDynamicBoxTargetPosition(position, direction, getTopLayerPosition());
		damp3(dynamicBoxRef.current.position, targetPosition, 0.25, delta, speed, undefined, 0.1);

		if (isBeyoundScreen(position, direction)) {
			endGame(LossReason.BeyoundScreen);
		}
		if (checkIfTopBoxFalls()) {
			endGame(LossReason.TowerCollapsed);
		}

		frameAccurateBoxHitEffect();
	});

	return (
		<group>
			{isGameStarted && (
				<Box ref={dynamicBoxRef} position={dynamicPizzaBox.position}>
					<boxGeometry args={dynamicPizzaBox.args} />
					<PizzaBoxMaterial
						args={dynamicPizzaBox.args}
						boxTexture={dynamicPizzaBox.boxTexture}
						textureOffset={dynamicPizzaBox.textureOffset}
					/>
				</Box>
			)}
			{...pizzaBoxes.map(box => getPizzaBox(box))}
			{...fallingPizzaBoxes.map(box => getPizzaBox(box))}
			{getPizzaBox(bottomBox)}
			{accurateBoxHitEffect.isVisible && isGameStarted && (
				<Box
					ref={accurateBoxHitEffectRef}
					position={accurateBoxHitEffect.position}
					args={accurateBoxHitEffect.args}
					rotation={accurateBoxHitEffect.rotation}
				>
					<meshBasicMaterial opacity={accurateBoxHitEffect.opacity} color='white'>
						<GradientTexture
							colors={[`aquamarine`, `hotpink`]} // Colors need to match the number of stops
							stops={[0, 1]}
						/>
					</meshBasicMaterial>
				</Box>
			)}
		</group>
	);
});
