import { HeaderStyled, ResultStyled, TextStyled } from './result.styles';

export type GameResultProps = {
	pizzaBoxCount: number;
	startGame: () => void | undefined;
};

export const GameResult = (props: GameResultProps): JSX.Element => {
	const { pizzaBoxCount, startGame } = props;

	return (
		<ResultStyled>
			<HeaderStyled>You are the best!</HeaderStyled>
			<TextStyled>You earn {pizzaBoxCount}</TextStyled>
			<button type='button' className='orange-button' onClick={startGame}>
				Play again!
			</button>
		</ResultStyled>
	);
};
