import { logger } from 'shared/lib/logger';
import { GameEndedEvent, PlatformId, PointAddedEvent } from './event-api.model';

declare global {
	interface Window {
		// eslint-disable-next-line @typescript-eslint/no-explicit-any
		JSBridge?: any;
		webkit?: {
			// eslint-disable-next-line @typescript-eslint/no-explicit-any
			messageHandlers?: any;
		};
	}
}

export type MessageJSON = {
	event: string;
	data: string | undefined;
};

type sendFunction = (eventName: string, param?: string) => void;

// eslint-disable-next-line sonarjs/cognitive-complexity
const adapter = (client?: PlatformId): sendFunction => {
	/* eslint-disable @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call */
	if (client === PlatformId.Android) {
		if (!window.JSBridge) {
			logger.current.error(`window.JSBridge is not available for Android client`);

			return () => {};
		}

		return (eventName, ...params) => {
			if (!window.JSBridge?.[eventName]) {
				logger.current.warn(`${eventName} is not implemented on window.JSBridge`);

				return;
			}

			try {
				window.JSBridge[eventName](...params); // it's important to pass the exact number of parameters!
			} catch (error) {
				logger.current.error(`Error while calling window.JSBridge.${eventName}`, error);
			}
		};
	}

	if (client === PlatformId.IOS && !window.webkit) {
		logger.current.error(`window.webkit is not available for iOS client`);

		return () => {};
	}

	if (client === PlatformId.IOS && window.webkit) {
		return (eventName, param) => {
			if (!window.webkit?.messageHandlers?.[eventName]) {
				logger.current.warn(`${eventName} is not implemented on window.webkit.messagehandlers`);

				return;
			}

			try {
				window.webkit.messageHandlers[eventName].postMessage(param);
			} catch (error) {
				logger.current.error(`Error while calling window.webkit.messageHandlers.${eventName}`, error);
			}
		};
	}

	if (client === PlatformId.Web) {
		return (eventName, param) => {
			window.parent.postMessage(
				JSON.stringify({
					event: eventName,
					data: param,
				}),
				`*`,
			);
		};
	}

	if (client !== undefined && client !== PlatformId.None) {
		logger.current.error(`No adapter found for client platform: ${client}`);
	}

	return () => {};
	/* eslint-enable @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call */
};

export const eventsPublisher = {
	pointAdded: (event: PointAddedEvent, client?: PlatformId): void =>
		adapter(client)(`pointAdded`, JSON.stringify(event)),
	gameEnded: (event: GameEndedEvent, client?: PlatformId): void =>
		adapter(client)(`gameEnded`, JSON.stringify(event)),
	gameLoaded: (client?: PlatformId): void => adapter(client)(`gameLoaded`),
};
