import { BoxTexture } from 'pages/game/game.model';
import { defaultBoxes } from 'pages/game/textureBoxes/default';
import { winterBoxes } from 'pages/game/textureBoxes/winter';

const allTextures = {
	default: defaultBoxes,
	winter: winterBoxes,
};

Object.values(allTextures).forEach(textures => {
	textures.forEach(texture => {
		if (texture.upperSide) {
			// eslint-disable-next-line @typescript-eslint/ban-ts-comment
			// @ts-ignore
			// eslint-disable-next-line @typescript-eslint/naming-convention,@typescript-eslint/no-unused-vars
			const _ = texture.upperSide;
		}
		if (texture.rightSide) {
			// eslint-disable-next-line @typescript-eslint/ban-ts-comment
			// @ts-ignore
			// eslint-disable-next-line @typescript-eslint/naming-convention,@typescript-eslint/no-unused-vars
			const _ = texture.rightSide;
		}
		if (texture.leftSide) {
			// eslint-disable-next-line @typescript-eslint/ban-ts-comment
			// @ts-ignore
			// eslint-disable-next-line @typescript-eslint/naming-convention,@typescript-eslint/no-unused-vars
			const _ = texture.leftSide;
		}
	});
});

export const getTextureBoxes = (): BoxTexture[] => {
	const { gameMode } = window;

	// eslint-disable-next-line @typescript-eslint/no-unnecessary-condition
	return allTextures[gameMode] || defaultBoxes;
};
