import { createLoggerInstanceRef, ILoggerInstanceRef } from '@dodopizza/react-logger';

import { PlatformId } from 'pages/game/event-api.model';
import { ApplicationName } from 'shared/constants/global';

export const testLoggerUrl = `https://frontlogger.dev.dodois.dev/`;
export const prodLoggerUrl = `https://frontlogger.dodois.io/`;

const getPlatformName = (client: PlatformId | undefined): string => {
	switch (client) {
		case PlatformId.Android:
			return `Android`;
		case PlatformId.IOS:
			return `iOS`;
		default:
			return ``;
	}
};

const createLogger = (environmentUrl: string | undefined): ILoggerInstanceRef => {
	const isProdEnvironment = environmentUrl?.includes(`dodois.dev`) === false;

	return createLoggerInstanceRef({
		applicationName: ApplicationName,
		isProduction: (import.meta as any).env?.PROD,
		environmentName: environmentUrl ?? `local`,
		remoteUrl: isProdEnvironment ? prodLoggerUrl : testLoggerUrl,
	});
};

export const logger = createLogger(undefined);

export const updateLogger = (params: {
	environmentUrl?: string;
	countryId?: number;
	client?: PlatformId;
	clientVersion?: string;
	accountId?: string;
	orderId?: string;
}): void => {
	logger.current = createLogger(params.environmentUrl).current;
	logger.enrichScope({
		countryId: params.countryId,
		client: getPlatformName(params.client),
		clientVersion: params.clientVersion,
	});
};

export const enrichLoggerWithScope = (params: { clientId?: string; orderId?: string }): void => {
	logger.enrichScope({
		clientId: params.clientId,
		orderId: params.orderId,
	});
};
